mapper.select:
select i.invite_id, i.project_id, i.invitee_user_id, i.status, i.inviter_by, i.invite_time, i.handle_by, i.handle_time, i.create_by, i.create_time, i.update_by, i.update_time, i.deleted, p.title as project_title, u.nick_name as inviter_nick_name from project_invite i inner join project p on i.project_id = p.project_id and p.deleted = 0 left join sys_user u on p.author_id = u.user_id where i.deleted = 0 and i.invitee_user_id = #{inviteeUserId}
and i.status = #{status}
order by i.invite_time desc, i.invite_id desc
